 * key must follow what dart.sh resolves FROM THE CHECKOUT — the sandbox
 * carries the quality.yml fixture). Returns { rc, out } with merged output.
 */
function dsCacheRun(argsLine, opts) {
    opts = opts || {};
    var lines = ['r="$(pwd)"', 'd="$(mktemp -d)"'];
