    });

    test('quality.yml setup-dart step without channel → stable from detection (source=quality workflow)', function () {
        var noChannel = DS_QUALITY_BETA.replace('          channel: beta\n', '');
        var r = dsRun('plan', { qualityYml: noChannel });
