        'bash "$r/setup/cache.sh" ' + argsLine + ') 2>&1"); rc=$?');
    lines.push('printf "__RC__=%s\\n" "$rc"');
    lines.push('printf "%s\\n" "$out"');
    lines.push('cd /; rm -rf "$d"; exit 0');
