    var env = (opts.env || []).slice();
    env.push('DART_INSTALL_DIR="$d/nodart"');
    lines.push('cd "$d"');
    lines.push('out="$((' + (env.length ? env.join(' ') + ' ' : '') +
        'bash "$r/setup/dart.sh" ' + subcommand + ') 2>&1"); rc=$?');
    lines.push('printf "__RC__=%s\\n" "$rc"');
