81:function dsRun(subcommand, opts) {
82:    opts = opts || {};
83:    var lines = ['r="$(pwd)"', 'd="$(mktemp -d)"'];
84:    if (opts.qualityYml !== undefined) {
85:        lines.push('mkdir -p "$d/.github/workflows"');
86:        lines.push('printf %s ' + dsShq(opts.qualityYml) + ' > "$d/.github/workflows/quality.yml"');
87:    }
88:    if (opts.stubDart !== undefined) {
89:        lines.push('mkdir -p "$d/bin"');
90:        // The banner is quoted INSIDE the stub script (dsShq(opts.stubDart) rides
91:        // inside the script text, not as a shell argument) — an unquoted echo
92:        // would die on the banner's parentheses and print no version at all.
93:        lines.push('printf %s ' + dsShq('#!/bin/sh\necho ' + dsShq(opts.stubDart)) + ' > "$d/bin/dart"');
94:        lines.push('chmod +x "$d/bin/dart"');
95:    }
96:    var env = (opts.env || []).slice();
97:    // Hermetic against the HOST: the script's installed-version probe falls
98:    // back to <DART_INSTALL_DIR>/dart-sdk/bin/dart, so a real SDK cached on
99:    // the runner (or left by a manual install — live: the verification step
100:    // of this very ticket) would leak into `status`/`plan`. Point the
101:    // install dir INSIDE the sandbox for every invocation.
102:    env.push('DART_INSTALL_DIR="$d/nodart"');
103:    if (opts.stubDart !== undefined) {
104:        env.push('PATH="$d/bin:$PATH"');
105:    }
106:    lines.push('cd "$d"');
107:    lines.push((env.length ? env.join(' ') + ' ' : '') +
108:        'bash "$r/setup/dart.sh" ' + subcommand);
109:    lines.push('rc=$?; cd /; rm -rf "$d"; exit $rc');
110:    return dsParseKv(cli_execute_command({ command: 'bash -c ' + dsShq(lines.join('\n')) }));
111:}
