```js
if (opts.trailTarget !== undefined) {
    lines.push('dpath=' + dsShq(opts.trailTarget));
    lines.push('before=$(wc -l < /tmp/_registered_paths 2>/dev/null || echo 0)');
    lines.push('touch /tmp/_registered_paths');
    // run happens next...
}
