        // the same value and derive the same key.
        var restore = dsCacheRun('keys dart', { env: ['DART_VERSION=beta'] });
        var save = dsCacheRun('keys dart', { env: ['DART_VERSION=beta'] });
        var keyOf = function (o) {
            var m = /key=([^\s]+)/.exec(o.out);
            return m ? m[1] : '(none)';
        };
